positional:
var sv=window.SugarCube.State.variables;
return JSON.stringify({
  passage: window.SugarCube.State.passage,
  phoneActive: !!(sv.flags && sv.flags.phone_active),
  phoneBtnInDOM: jQuery('#phone-sidebar-btn').length,
  bodyHead: (document.querySelector('.passage') ? document.querySelector('.passage').innerText.slice(0,180) : ''),
  links: jQuery('.passage a, #passages a').map(function(){return jQuery(this).text();}).get().slice(0,10)
});

return JSON.stringify({
  passage: window.SugarCube.State.passage,
  allLinks: jQuery('a').map(function(){var t=jQuery(this).text().trim(); return t? t : null;}).get().filter(Boolean).slice(0,20)
});

var el = jQuery('a').filter(function(){return jQuery(this).text().indexOf('18 or older')>-1;})[0];
return JSON.stringify({
  found: !!el,
  tag: el? el.tagName: null,
  cls: el? el.className: null,
  onclick: el? (el.getAttribute('onclick')||'').slice(0,80): null,
  macro: el? (el.getAttribute('data-passage')||el.getAttribute('href')||''): null,
  outer: el? el.outerHTML.slice(0,160): null,
  startPassage: window.SugarCube.Config.passages.start
});

var w=window, S=w.SugarCube, sv=S.State.variables;
w.applyFlagEffect('player', null, 'phone_active', 'set');
w.applyFlagEffect('player', null, 'frank_caught', 'set');
w.applyFlagEffect('player', null, 'jake_peek_draw_revealed', 'set');
w.applyFlagEffect('player', null, 'ryan_help_tier_open', 'set');
sv.player.core_traits.corruption = 50;
return JSON.stringify({phone_active:!!sv.flags.phone_active, frank_caught:!!sv.flags.frank_caught, corruption:sv.player.core_traits.corruption});

return JSON.stringify({
  phoneBtn: jQuery('#phone-sidebar-btn').length,
  phoneBtnText: jQuery('#phone-sidebar-btn').text().trim(),
  badge: jQuery('.phone-badge').text().trim()
});

return JSON.stringify({
  view: window.SugarCube.setup._phoneView,
  appTiles: jQuery('.phone-app-tile, .phone-app, [data-app]').map(function(){return jQuery(this).text().trim();}).get(),
  frameText: jQuery('.phone-frame').text().replace(/\s+/g,' ').slice(0,200)
});

// click the Messages app tile
var tile = jQuery('.phone-frame [data-app-id], .phone-frame .phone-app-icon, .phone-frame [data-app]').filter(function(){return jQuery(this).text().indexOf('Messages')>-1;})[0]
       || jQuery('.phone-frame *').filter(function(){return jQuery(this).text().trim()==='Messages';}).last()[0];
if(tile) tile.click();
return JSON.stringify({clicked:!!tile, view: window.SugarCube.setup._phoneView});

return JSON.stringify({
  view: window.SugarCube.setup._phoneView,
  threads: jQuery('.phone-thread').map(function(){return jQuery(this).text().replace(/\s+/g,' ').trim().slice(0,50);}).get()
});

var names = jQuery('.phone-thread-name, .phone-thread-item, [data-thread], [data-conv-id], [data-conversation]').map(function(){return jQuery(this).text().replace(/\s+/g,' ').trim().slice(0,40);}).get();
return JSON.stringify({
  threadNames: names,
  screenText: jQuery('.phone-screen').text().replace(/\s+/g,' ').slice(0,260),
  threadEls: jQuery('.phone-thread-list > *').length
});

var fr = jQuery('.phone-thread').filter(function(){return jQuery(this).text().indexOf('Frank')>-1;})[0];
if(fr) fr.click();
return JSON.stringify({clicked:!!fr, view: window.SugarCube.setup._phoneView});

return JSON.stringify({
  bubbles: jQuery('.phone-msg, .phone-bubble, .phone-message').map(function(){return jQuery(this).text().replace(/\s+/g,' ').trim().slice(0,60);}).get(),
  replyChoices: jQuery('.phone-reply-choice, .phone-reply button, .phone-reply a, [data-choice]').map(function(){return jQuery(this).text().replace(/\s+/g,' ').trim();}).get()
});

return JSON.stringify({
  screen: jQuery('.phone-screen').text().replace(/\s+/g,' ').trim().slice(0,300),
  choiceEls: jQuery('.phone-screen [data-choice-index], .phone-reply-btn, .phone-chat-choice').map(function(){return (jQuery(this).text().trim()+' ['+(jQuery(this).attr('class')||'')+']').slice(0,60);}).get()
});

var sv=window.SugarCube.State.variables;
var fid=window.SugarCube.setup.resolveNpcId('npc_frank');
window._trustBefore = sv.npcs[fid].core_traits.trust;
window._termsBefore = !!sv.flags.frank_terms_accepted;
jQuery('.phone-reply-btn').filter(function(){return jQuery(this).text().indexOf('Okay. Your terms')>-1;})[0].click();
return 'clicked';

var sv=window.SugarCube.State.variables;
var fid=window.SugarCube.setup.resolveNpcId('npc_frank');
return JSON.stringify({
  trustBefore: window._trustBefore, trustAfter: sv.npcs[fid].core_traits.trust,
  termsBefore: window._termsBefore, termsAfter: !!sv.flags.frank_terms_accepted,
  screenTail: jQuery('.phone-screen').text().replace(/\s+/g,' ').trim().slice(-80)
});

var sv=window.SugarCube.State.variables;
window._corrB = sv.player.core_traits.corruption; window._arB = sv.player.core_traits.arousal;
var b=jQuery('.phone-screen *').filter(function(){return jQuery(this).text().trim()==='[Send a lewd photo]';}).last()[0] 
   || jQuery('.phone-daily-topic, .phone-topic-btn, .phone-screen [data-topic-id]').filter(function(){return jQuery(this).text().indexOf('lewd')>-1;})[0];
if(b) b.click();
return JSON.stringify({clicked:!!b});

var sv=window.SugarCube.State.variables; var fid=window.SugarCube.setup.resolveNpcId('npc_frank');
return JSON.stringify({
  corr: window._corrB+'→'+sv.player.core_traits.corruption,
  arousal: window._arB+'→'+sv.player.core_traits.arousal,
  frankArousal: sv.npcs[fid].core_traits.arousal,
  lewdNowLocked: jQuery('.phone-screen').text().indexOf('🔒')>-1 ? jQuery('.phone-screen').text().replace(/\s+/g,' ').match(/.{0,12}lewd.{0,20}/i): 'n/a',
  screenTail: jQuery('.phone-screen').text().replace(/\s+/g,' ').trim().slice(-120)
});
